inputs = ['wvzkvg', 'dfibbb', 'iguf', 'ecj', 'iyzxdz']
outputs = ['wvzkvg', 'fwahfwibbb', 'iguahfw', 'ecyga', 'iyzxfwz']

for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Input {i}: '{inp}' -> Output {i}: '{outp}'")

    # Let's see how many characters differ
    min_len = min(len(inp), len(outp))
    print(f"  Length: {len(inp)} -> {len(outp)}")
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        elif j < len(inp):
            print(f"  Position {j}: '{inp[j]}' (removed)")
        elif j < len(outp):
            print(f"  Position {j}: '{outp[j]}' (added)")
    print()

